import advisoryData from "@/data/travel_advisories.json";
import countryCodes from "@/data/country_codes.json";

// Generated by data/scripts/generate_advisories.py from the State Dept CSV
export type Advisory = {
  level: 1 | 2 | 3 | 4;
  description: string;
  risks: string[];
  issued: string;
  snapshot: string;
};

const advisories = advisoryData as Record<string, Advisory>;

export const ADVISORY_URL = "https://travel.state.gov/en/international-travel/travel-advisories.html";

export const getAdvisory = (country: string): Advisory | null => advisories[country] ?? null;

// ISO2 code -> flag emoji via regional indicator symbols ("ES" -> 🇪🇸)
export const getFlag = (country: string): string => {
  const code = (countryCodes as Record<string, string>)[country];
  return code ? String.fromCodePoint(...[...code.toUpperCase()].map((c) => 0x1f1a5 + c.charCodeAt(0))) : "";
};

export const ADVISORY_LEVELS: Record<Advisory["level"], { short: string; color: string }> = {
  1: { short: "Normal precautions", color: "bg-green-100 text-green-700" },
  2: { short: "Increased caution", color: "bg-yellow-100 text-yellow-700" },
  3: { short: "Reconsider travel", color: "bg-orange-100 text-orange-700" },
  4: { short: "Do not travel", color: "bg-red-100 text-red-700" },
};

